    "rawContent": "TYPE is designed for writing. You don't have to worry about accidentally triggering home row mods while typing. If the AutoShift settings aren't working for you, you can adjust them here. You can even toggle it if you'd rather have a (mostly) classic typing experience.\n\nYou may also notice that I separated Up/Dn from PgUp/PgDn. The GAME toggle on the left and the NPAD toggle on the right creates a vertical space (for Up/Dn) on the left and a horizontal space (Left/Right) on the right. PgUp/PgDn is on the same side as Up/Dn, and Home/End is on the same side as Left/Right."
