    "rawContent": "SYM1 is the main symbol support layer. The access key is on the home position of the right thumb.\n\nSYM1 is a bit chaotic, but I tried to organize it with these ideas:\n1) Enclosing punctuation (like parenthesis) in the middle.\n2) Opposing symbols on opposite sides of the center line.\n3) Put symbols in analogous positions where some version of them appears on other layers.\n4) Unshifted symbols go in SYM1."
