    "text": "Клавиатура работает полностью без проводов (питание от аккумуляторов). Связь с компьютером осуществляется через беспроводной USB-донгл (приемник), а также напрямую через Bluetooth:\n\n- **Dongle**: мгновенное переключение на беспроводной USB-ресивер ПК (профиль 0).\n- **BT 1 .. BT 4**: прямое сопряжение с дополнительными устройствами по Bluetooth (ноутбук, смартфон, планшет).\n- **Dgl/BT**: быстрый тумблер переключения между ПК (через донгл) и Bluetooth-устройствами.\n- **BT Clr**: сброс сопряжения для переподключения устройства.\n- *Программный Reset удален — для прошивки используется аппаратная кнопка на плате.*",
