    "rawContent": "There is some logic to the positions of the operators. \"Divide/Forward slash\" and \"Modulus/Backslash\" are the same positions as they are in WORK. \"Minus/Hyphen\" is \"up\" above divide, close to where it would appear on a normal keyboard (but moved closer for ease of reach). The positive versions of divide and minus, \"Multiply/Asterisk\" and \"Plus\" are on the same row but opposite side of the number block as their negative counterparts. \"Equals\" takes the place of \"Enter\", which is conceptually the same thing."
