    "rawContent": "I can use these modifiers comfortably using one shot modifiers. They act like normal modifiers if you hold them. They will activate the mod for your next keypress if you tap them. I set ONESHOT_TAP_TOGGLE to 2, so I can lock the modifiers by double-tapping them. If the modifier gets stuck, FUNC OFF also clears one shot mods."
