    "summary": "Генератор последовательностей чисел от 1 до 255.",
    "text": "Тап печатает следующее число (1, 2, 3...). Длинное нажатие сбрасывает счетчик на 1. Shift меняет направление или режим на буквы (A, B, C...).",
    "rawContent": "Each keypress of AutoNumber prints the next letter or number in a sequence from 1-255. C=Ctrl, S=Shift, T=Tap, P=Long Press:\n\n1) T: Move next. Print.\n2) P: Reset to 1. Don't print.\n3) S+T: Toggle increment/decrement. Don't print.\n4) S+P: Reset to 1. Toggle letter/number. Don't print.\n5) C+T: Don't move. Print.\n6) S+C+T: Move next. Don't print.\n7) S+C+P: Move next (x10). Don't print.\n\nThis is complicated to use. TBH, I have to spend a few moments figuring it out if I haven't used it in a while. I usually use this as a part of a dynamic macro. It can also fill out a keyboard layout very quickly."
